import{_ as t,a0 as o,w as p,s as d,I as a,x as s,a1 as l,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"使用 Conda 管理 MacOS 上的 Ansible 環境 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Conda 管理 MacOS 上的 Ansible 環境 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Conda 管理 MacOS 上的 Ansible 環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Conda 管理 MacOS 上的 Ansible 環境 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190828 Managing Ansible environments on MacOS with Conda","title":"使用 Conda 管理 MacOS 上的 Ansible 環境","tag":"201909","desc":""},"relativePath":"201909/20190828 Managing Ansible environments on MacOS with Conda.md","filePath":"[post].md"}'),b={name:"201909/20190828 Managing Ansible environments on MacOS with Conda.md"};function u(h,n,g,m,f,k){const e=o("Link");return p(),d("div",null,[n[34]||(n[34]=a("h1",{id:"使用-conda-管理-macos-上的-ansible-環境",tabindex:"-1"},[s("使用 Conda 管理 MacOS 上的 Ansible 環境 "),a("a",{class:"header-anchor",href:"#使用-conda-管理-macos-上的-ansible-環境","aria-label":"Permalink to “使用 Conda 管理 MacOS 上的 Ansible 環境”"},"​")],-1)),n[35]||(n[35]=a("blockquote",null,[a("p",null,"Conda 將 Ansible 所需的一切都收集到虛擬環境中並將其與其他項目分開。")],-1)),n[36]||(n[36]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201909/18/123838m1bcmke570kl6kzm.jpg",alt:""})],-1)),n[37]||(n[37]=a("p",null,"如果你是一名使用 MacOS 並涉及到 Ansible 管理的 Python 開發人員，你可能希望使用 Conda 包管理器將 Ansible 的工作內容與核心操作系統和其他本地項目分開。",-1)),n[38]||(n[38]=a("p",null,"Ansible 基於 Python。要讓 Ansible 在 MacOS 上工作，Conda 並不是必須要的，但是它確實讓你管理 Python 版本和包依賴變得更加容易。這允許你在 MacOS 上使用升級的 Python 版本，並在你的系統中、Ansible 和其他編程項目之間保持 Python 包的依賴性相互獨立。",-1)),a("p",null,[n[1]||(n[1]=s("在 MacOS 上安裝 Ansible 還有其他方法。你可以使用 ",-1)),l(e,{href:"https://brew.sh/"},{default:i(()=>[...n[0]||(n[0]=[s("Homebrew",-1)])]),_:1}),n[2]||(n[2]=s("，但是如果你對 Python 開發（或 Ansible 開發）感興趣，你可能會發現在一個獨立 Python 虛擬環境中管理 Ansible 可以減少一些混亂。我覺得這更簡單；與其試圖將 Python 版本和依賴項加載到系統或 ",-1)),n[3]||(n[3]=a("code",null,"/usr/local",-1)),n[4]||(n[4]=s(" 目錄中 ，還不如使用 Conda 幫助我將 Ansible 所需的一切都收集到一個虛擬環境中，並將其與其他項目完全分開。",-1))]),n[39]||(n[39]=a("p",null,"本文着重於使用 Conda 作為 Python 項目來管理 Ansible，以保持它的乾淨並與其他項目分開。請繼續閲讀，並瞭解如何安裝 Conda、創建新的虛擬環境、安裝 Ansible 並對其進行測試。",-1)),n[40]||(n[40]=a("h3",{id:"序幕",tabindex:"-1"},[s("序幕 "),a("a",{class:"header-anchor",href:"#序幕","aria-label":"Permalink to “序幕”"},"​")],-1)),a("p",null,[n[6]||(n[6]=s("最近，我想學習 ",-1)),l(e,{href:"https://docs.ansible.com/?extIdCarryOver=true&sc_cid=701f2000001OH6uAAG"},{default:i(()=>[...n[5]||(n[5]=[s("Ansible",-1)])]),_:1}),n[7]||(n[7]=s("，所以我需要找到安裝它的最佳方法。",-1))]),n[41]||(n[41]=a("p",null,"我通常對在我的日常工作站上安裝東西很謹慎。我尤其不喜歡對供應商的默認操作系統安裝應用手動更新（這是我多年作為 Unix 系統管理的習慣）。我真的很想使用 Python 3.7，但是 MacOS 的 Python 包是舊的 2.7，我不會安裝任何可能干擾核心 MacOS 系統的全局 Python 包。",-1)),n[42]||(n[42]=a("p",null,"所以，我使用本地 Ubuntu 18.04 虛擬機上開始了我的 Ansible 工作。這提供了真正意義上的的安全隔離，但我很快發現管理它是非常乏味的。所以我着手研究如何在本機 MacOS 上獲得一個靈活但獨立的 Ansible 系統。",-1)),n[43]||(n[43]=a("p",null,"由於 Ansible 基於 Python，Conda 似乎是理想的解決方案。",-1)),n[44]||(n[44]=a("h3",{id:"安裝-conda",tabindex:"-1"},[s("安裝 Conda "),a("a",{class:"header-anchor",href:"#安裝-conda","aria-label":"Permalink to “安裝 Conda”"},"​")],-1)),a("p",null,[n[9]||(n[9]=s("Conda 是一個開源軟件，它提供方便的包和環境管理功能。它可以幫助你管理多個版本的 Python、安裝軟件包依賴關係、執行升級和維護項目隔離。如果你手動管理 Python 虛擬環境，Conda 將有助於簡化和管理你的工作。瀏覽 ",-1)),l(e,{href:"https://conda.io/projects/conda/en/latest/index.html"},{default:i(()=>[...n[8]||(n[8]=[s("Conda 文檔",-1)])]),_:1}),n[10]||(n[10]=s("可以瞭解更多細節。",-1))]),a("p",null,[n[12]||(n[12]=s("我選擇了 ",-1)),l(e,{href:"https://docs.conda.io/en/latest/miniconda.html"},{default:i(()=>[...n[11]||(n[11]=[s("Miniconda",-1)])]),_:1}),n[13]||(n[13]=s(" Python 3.7 安裝在我的工作站中，因為我想要最新的 Python 版本。無論選擇哪個版本，你都可以使用其他版本的 Python 安裝新的虛擬環境。",-1))]),n[45]||(n[45]=r(`<p>要安裝 Conda，請下載 PKG 格式的文件，進行通常的雙擊，並選擇 “Install for me only” 選項。安裝在我的系統上佔用了大約 158 兆的空間。</p><p>安裝完成後，調出一個終端來查看你有什麼了。你應該看到：</p><ul><li>在你的家目錄中的 <code>miniconda3</code> 目錄</li><li>shell 提示符被修改為 <code>(base)</code></li><li><code>.bash_profile</code> 文件更新了一些 Conda 特有的設置內容</li></ul><p>現在基礎已經安裝好了，你有了第一個 Python 虛擬環境。運行 Python 版本檢查可以證明這一點，你的 <code>PATH</code> 將指向新的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(base) $ which python</span></span>
<span class="line"><span>/Users/jfarrell/miniconda3/bin/python</span></span>
<span class="line"><span>(base) $ python --version</span></span>
<span class="line"><span>Python 3.7.1</span></span></code></pre></div><p>現在安裝了 Conda，下一步是建立一個虛擬環境，然後安裝 Ansible 並運行。</p><h3 id="為-ansible-創建虛擬環境" tabindex="-1">為 Ansible 創建虛擬環境 <a class="header-anchor" href="#為-ansible-創建虛擬環境" aria-label="Permalink to “為 Ansible 創建虛擬環境”">​</a></h3><p>我想將 Ansible 與我的其他 Python 項目分開，所以我創建了一個新的虛擬環境並切換到它:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(base) $ conda create --name ansible-env --clone base</span></span>
<span class="line"><span>(base) $ conda activate ansible-env</span></span>
<span class="line"><span>(ansible-env) $ conda env list</span></span></code></pre></div><p>第一個命令將 Conda 庫克隆到一個名為 <code>ansible-env</code> 的新虛擬環境中。克隆引入了 Python 3.7 版本和一系列默認的 Python 模組，你可以根據需要添加、刪除或升級這些模組。</p><p>第二個命令將 shell 上下文更改為這個新的環境。它為 Python 及其包含的模組設置了正確的路徑。請注意，在 <code>conda activate ansible-env</code> 命令後，你的 shell 提示符會發生變化。</p><p>第三個命令不是必須的；它列出了安裝了哪些 Python 模組及其版本和其他數據。</p><p>你可以隨時使用 Conda 的 <code>activate</code> 命令切換到另一個虛擬環境。這將帶你回到基本環境：<code>conda base</code>。</p><h3 id="安裝-ansible" tabindex="-1">安裝 Ansible <a class="header-anchor" href="#安裝-ansible" aria-label="Permalink to “安裝 Ansible”">​</a></h3><p>安裝 Ansible 有多種方法，但是使用 Conda 可以將 Ansible 版本和所有需要的依賴項打包在一個地方。Conda 提供了靈活性，既可以將所有內容分開，又可以根據需要添加其他新環境（我將在後面演示）。</p><p>要安裝 Ansible 的相對較新版本，請使用:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(base) $ conda activate ansible-env</span></span>
<span class="line"><span>(ansible-env) $ conda install -c conda-forge ansible</span></span></code></pre></div><p>由於 Ansible 不是 Conda 默認通道的一部分，因此 <code>-c</code> 用於從備用通道搜索和安裝。Ansible 現已安裝到 <code>ansible-env</code> 虛擬環境中，可以使用了。</p><h3 id="使用-ansible" tabindex="-1">使用 Ansible <a class="header-anchor" href="#使用-ansible" aria-label="Permalink to “使用 Ansible”">​</a></h3><p>既然你已經安裝了 Conda 虛擬環境，就可以使用它了。首先，確保要控制的節點已將工作站的 SSH 密鑰安裝到正確的用户帳户。</p><p>調出一個新的 shell 並運行一些基本的 Ansible 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(base) $ conda activate ansible-env</span></span>
<span class="line"><span>(ansible-env) $ ansible --version</span></span>
<span class="line"><span>ansible 2.8.1</span></span>
<span class="line"><span>  config file = None</span></span>
<span class="line"><span>  configured module search path = [&#39;/Users/jfarrell/.ansible/plugins/modules&#39;, &#39;/usr/share/ansible/plugins/modules&#39;]</span></span>
<span class="line"><span>  ansible python module location = /Users/jfarrell/miniconda3/envs/ansibleTest/lib/python3.7/site-packages/ansible</span></span>
<span class="line"><span>  executable location = /Users/jfarrell/miniconda3/envs/ansibleTest/bin/ansible</span></span>
<span class="line"><span>  python version = 3.7.1 (default, Dec 14 2018, 13:28:58) [Clang 4.0.1 (tags/RELEASE_401/final)]</span></span>
<span class="line"><span>(ansible-env) $ ansible all -m ping -u ansible</span></span>
<span class="line"><span>192.168.99.200 | SUCCESS =&gt; {</span></span>
<span class="line"><span>    &quot;ansible_facts&quot;: {</span></span>
<span class="line"><span>        &quot;discovered_interpreter_python&quot;: &quot;/usr/bin/python&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;changed&quot;: false,</span></span>
<span class="line"><span>    &quot;ping&quot;: &quot;pong&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在 Ansible 工作了，你可以在控制台中抽身，並從你的 MacOS 工作站中使用它們。</p><h3 id="克隆新的-ansible-進行-ansible-開發" tabindex="-1">克隆新的 Ansible 進行 Ansible 開發 <a class="header-anchor" href="#克隆新的-ansible-進行-ansible-開發" aria-label="Permalink to “克隆新的 Ansible 進行 Ansible 開發”">​</a></h3><p>這部分完全是可選的；只有當你想要額外的虛擬環境來修改 Ansible 或者安全地使用有問題的 Python 模組時，才需要它。你可以通過以下方式將主 Ansible 環境克隆到開發副本中:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(ansible-env) $ conda create --name ansible-dev --clone ansible-env</span></span>
<span class="line"><span>(ansible-env) $ conda activte ansible-dev</span></span>
<span class="line"><span>(ansible-dev) $</span></span></code></pre></div><h3 id="需要注意的問題" tabindex="-1">需要注意的問題 <a class="header-anchor" href="#需要注意的問題" aria-label="Permalink to “需要注意的問題”">​</a></h3><p>偶爾你可能遇到使用 Conda 的麻煩。你通常可以通過以下方式刪除不良環境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ conda activate base</span></span>
<span class="line"><span>$ conda remove --name ansible-dev --all</span></span></code></pre></div><p>如果出現無法解決的錯誤，通常可以通過在 <code>~/miniconda3/envs</code> 中找到該環境並刪除整個目錄來直接刪除環境。如果基礎環境損壞了，你可以刪除整個 <code>~/miniconda3</code>，然後從 PKG 文件中重新安裝。只要確保保留 <code>~/miniconda3/envs</code> ，或使用 Conda 工具導出環境配置並在以後重新創建即可。</p>`,30)),a("p",null,[n[15]||(n[15]=s("MacOS 上不包括 ",-1)),n[16]||(n[16]=a("code",null,"sshpass",-1)),n[17]||(n[17]=s(" 程序。只有當你的 Ansible 工作要求你向 Ansible 提供 SSH 登錄密碼時，才需要它。你可以在 SourceForge 上找到當前的 ",-1)),l(e,{href:"https://sourceforge.net/projects/sshpass/"},{default:i(()=>[...n[14]||(n[14]=[s("sshpass 源代碼",-1)])]),_:1}),n[18]||(n[18]=s("。",-1))]),n[46]||(n[46]=a("p",null,[s("最後，基礎的 Conda Python 模組列表可能缺少你工作所需的一些 Python 模組。如果你需要安裝一個模組，首選命令是 "),a("code",null,"conda install package"),s("，但是需要的話也可以使用 "),a("code",null,"pip"),s("，Conda 會識別安裝的模組。")],-1)),n[47]||(n[47]=a("h3",{id:"結論",tabindex:"-1"},[s("結論 "),a("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),n[48]||(n[48]=a("p",null,"Ansible 是一個強大的自動化工具，值得我們去學習。Conda 是一個簡單有效的 Python 虛擬環境管理工具。",-1)),n[49]||(n[49]=a("p",null,"在你的 MacOS 環境中保持軟件安裝分離是保持日常工作環境的穩定性和健全性的謹慎方法。Conda 尤其有助於升級你的 Python 版本，將 Ansible 從其他項目中分離出來，並安全地使用 Ansible。",-1)),n[50]||(n[50]=a("hr",null,null,-1)),a("p",null,[n[20]||(n[20]=s("via: ",-1)),l(e,{href:"https://opensource.com/article/19/8/using-conda-ansible-administration-macos"},{default:i(()=>[...n[19]||(n[19]=[s("https://opensource.com/article/19/8/using-conda-ansible-administration-macos",-1)])]),_:1})]),a("p",null,[n[25]||(n[25]=s("作者：",-1)),l(e,{href:"https://opensource.com/users/jamesf"},{default:i(()=>[...n[21]||(n[21]=[s("James Farrell",-1)])]),_:1}),n[26]||(n[26]=s(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[22]||(n[22]=[s("lujun9972",-1)])]),_:1}),n[27]||(n[27]=s(" 譯者：",-1)),l(e,{href:"https://github.com/heguangzhi"},{default:i(()=>[...n[23]||(n[23]=[s("heguangzhi",-1)])]),_:1}),n[28]||(n[28]=s(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...n[24]||(n[24]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[31]||(n[31]=s("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[29]||(n[29]=[s("LCTT",-1)])]),_:1}),n[32]||(n[32]=s(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...n[30]||(n[30]=[s("Linux中國",-1)])]),_:1}),n[33]||(n[33]=s(" 榮譽推出",-1))])])}const v=t(b,[["render",u]]);export{A as __pageData,v as default};
